@if($paginator->hasPages())<nav class="mmc-shop-pagination" aria-label="Product pages">@if($paginator->onFirstPage())<span aria-disabled="true">Previous</span>@else<a href="{{ $paginator->previousPageUrl() }}">Previous</a>@endif @foreach($elements as $element)@if(is_string($element))<span>{{ $element }}</span>@else @foreach($element as $number=>$url)<a href="{{ $url }}" @if($number===$paginator->currentPage()) aria-current="page" @endif>{{ $number }}</a>@endforeach @endif @endforeach @if($paginator->hasMorePages())<a href="{{ $paginator->nextPageUrl() }}">Next</a>@else<span aria-disabled="true">Next</span>@endif</nav>@endif
